 "content": "def transform(grid):
    """Extend the repeated parallel-stripe motif across the whole grid."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Each possible stripe orientation has a coordinate that is constant on
    # its stripes: horizontal, vertical, NW-SE, or NE-SW.
    coordinates = (
        ("row", lambda r, c: r),
        ("column", lambda r, c: c),
        ("diagonal", lambda r, c: c - r),
        ("anti_diagonal", lambda r, c: r + c),
    )
    candidates = []
    for name, coord in coordinates:
        bands = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    bands.setdefault(coord(r, c), set()).add(color)
        # A real stripe orientation has a single color along each marked band.
        if not bands or any(len(colors) != 1 for colors in bands.values()):
            continue
        period = len(bands)
        residues = {}
        consistent = True
        for band, colors in bands.items():
            residue = band % period
            color = next(iter(colors))
            if residue in residues and residues[residue] != color:
                consistent = False
                break
            residues[residue] = color
        if consistent and len(residues) == period:
            candidates.append((period, name, coord, residues))

    if not candidates:
        return [row[:] for row in grid]

    # The motif is represented by the smallest set of parallel marked bands.
    # Stable ordering resolves only genuinely tied orientations.
    _, _, coord, colors_by_residue = min(candidates, key=lambda item: item[0])
    return [
        [colors_by_residue[coord(r, c) % len(colors_by_residue)] for c in range(w)]
        for r in range(h)
    ]


if __name__ == "__main__":
    import json, sys
